class V3:
    def __init__(self, x, y):
        self.x = x
        self.y = y
    def __add__(self, o):
        return V3(self.x + o.x, self.y + o.y)
    def __mul__(self, k):
        return V3(self.x * k, self.y * k)
    def __eq__(self, o):
        return self.x == o.x and self.y == o.y
    def __str__(self):
        return '(' + str(self.x) + ',' + str(self.y) + ')'
print(V3(1, 2) + V3(3, 4))
print(V3(1, 2) * 3)
