def q2(a):
    if len(a) <= 1:
        return a
    p = a[0]
    left = []
    right = []
    for x in a[1:]:
        if x < p:
            left.append(x)
        else:
            right.append(x)
    return left + [p] + right
print(q2([8, 3, 9, 1]))

def q3(a):
