class Nd:
    def __init__(self, val):
        self.val = val
        self.next = None
class LL:
    def __init__(self):
        self.head = None
    def append(self, v):
        n = Nd(v)
        if self.head is None:
            self.head = n
            return
        cur = self.head
        while cur.next is not None:
            cur = cur.next
        cur.next = n
    def get(self):
        return self.head
